INSERT INTO leases (id, location_id, tenant_company_id, lease_name, lease_type, is_sub_lease, estatus, acquisition_type, lease_classification, rent_commencement_date, delivery_date, expiration_date, expiration_date_including_options, is_month_to_month, number_of_options, each_option_years, remaining_options, remaining_options_years, renewal_notice_period_start, renewal_notice_deadline, renewal_notice_intention, length_of_lease_months, landlord_nombre, landlord_parent_company, landlord_vendor_id, landlord_address1, landlord_address2, landlord_city, landlord_state, landlord_zip, landlord_country, landlord_poc_nombre, landlord_poc_telefono, landlord_poc_email, grace_period_dias, late_fee_type, late_fee_monto, security_deposit, rental_prepayments, rental_prepayments_detalle, remaining_lease_liability, percent_rent_yn, atributos_extra) VALUES ('c0c8e39d-0f1b-4a74-b3e4-ecbdf8752347', '9fa5eca6-8423-4c4a-bc20-8390a5157491', '83602737-ca9f-417e-b1ac-19d0ad371be6', 'Harbor Sublease: Mérida Retail Properties, S. de R.L. de C.V. (11/12/2025 - 11/11/2030)', NULL, true, 'activo', 'Lease', NULL, '2025-11-12', '2025-07-14', '2030-11-11', '2040-11-11', false, 2, NULL, 2, NULL, NULL, '2030-05-15', 'Send Notice to Renew', 59, 'Mérida Retail Properties, S. de R.L. de C.V.', NULL, NULL, 'Tablaje Catastral 24776', 'Progreso km. 15.5', 'Chablekal, Mérida', 'Yucatán', '97308', 'MX', 'Nancy Durán Martínez | José Manuel del Valle Luna | Mauricio Gerardo López Rivera', NULL, 'renta@inmobilia.mx | cfo@inmobilia.mx | dga@inmobilia.mx | legalofficer@inmobilia.mx', 120, 'percent', NULL, NULL, 781902, 'La Renta Anticipada se recibirá en calidad de depósito en garantía para el cumplimiento de las obligaciones de la Subarrendataria al Contrato y podrá ser aplicada para cubrir los primero 3 (tres) meses del Plazo de Vigencia hasta donde alcance, en el entendido de que, en caso de que la Subarrendataria no abra el Local Comercial al público en la fecha acordada en el Contrato, dicha Renta Anticipada servirá como fuente de pago de la pena convencional pactada por retraso en la apertura del Local Comercial al público, por lo que, desde este momento, la Subarrendataria autoriza a la Subarrendadora a retener y a tomar dicha cantidad en concepto de pago de convencional y a no aplicarlo al pago de Renta Mensual según lo pactado. Las Partes acuerdan que dicha cantidad no causará ningún interés a favor de la Subarrendataria, lo cual acepta expresamente esta última.', 15855202.07, false, '{"lease_total_rent_next_month":"299729.1000","lease_base_rent_change_months":2,"lease_total_rent_change_months":2,"total_monthly_rent":"299729.1000","annual_gross_rent":"3596749.2000","daily_gross_rent":"9854.10739726","recurring_rent_annual":"3596749.2000","lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"base_rent_current_month":"260634.0000","cam_current_month":"39095.1000","base_rent_next_month":"260634.0000","cam_next_month":"39095.1000","base_rent_per_square_meter":"1800.00","cam_per_square_meter":"270.00","base_rent_per_year":"3127608.0000","cam_per_year":"469141.2000"}'::jsonb);
