INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('c0c8e39d-0f1b-4a74-b3e4-ecbdf8752347', 'Late Fees', '7', '2', 'INTERESES MORATORIOS', E'- Si la Subarrendataria no paga a tiempo la Renta Mensual, la Cuota de Mantenimiento u otros pagos, deberá pagar intereses por el retraso.\n- Los intereses se calculan desde la fecha en que debió hacerse el pago hasta que se realice.\n- La tasa de interés es el doble de la Tasa de Interés Interbancaria de Equilibrio de Fondeo a 28 días (TIIEF), determinada por el Banco de México, dividida entre 12.\n- Se usa la TIIEF vigente al inicio del retraso o la más cercana a esa fecha.\n- Los intereses se calculan mensualmente, incluso si el retraso es de solo un día.', 'En caso de que la Subarrendataria no cubra puntualmente la Renta Mensual, la Cuota de Mantenimiento (según dicho término se define en la Cláusula Décima Cuarta del Contrato) y, cualesquiera otros pagos a que esté obligada conforme al Contrato, deberá cubrir intereses moratorios calculados a partir de la fecha en que debió haberse realizado el pago que corresponda y hasta la fecha en que efectivamente se haga el pago respectivo, a la tasa de interés que resulte de multiplicar por 2 (dos) la Tasa de Interés Interbancaria de Equilibrio de Fondeo a 28 (veintiocho) días ("TIIEF"), o la que la sustituya, en su caso, determinada por el Banco de México, y dividirla entre 12 (doce), por cada mes o fracción de mes que dure la mora. La tasa TIIEF que se utilizará será la que haya determinado Banco de México en la fecha del inicio de la mora, o a falta de esta, previa más cercana a dicha fecha. El cómputo de los intereses moratorios se hará por períodos mensuales, no obstante que la morosidad corresponda a un sólo día.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('c0c8e39d-0f1b-4a74-b3e4-ecbdf8752347', 'Incremento de Renta', '8', '2', 'INCREMENTO A LA RENTA FIJA', E'- The fixed rent will increase annually on the anniversary of the rent payment start date.\n- The increase is based on the inflation rate, calculated by comparing the National Consumer Price Index (INPC) of the current month with the INPC from the same month the previous year.\n- The new rent amount will apply for the next 12 months and will be recalculated each year.\n- For the first two years, the rent increase is capped at a maximum of 8% per year.', E'Las Partes convienen que, la Renta Fija se incrementará de forma anual en cada aniversario de la Fecha de Inicio de Pago de Renta, en el porcentaje de inflación resultante de comparar el Índice Nacional de Precios al Consumidor (el "INPC"), del mes correspondiente del año anterior con el INPC publicado en la fecha más cercana a la fecha de incremento. El resultado total que resulte de la operación anterior será la Renta Fija vigente para los siguientes 12 (doce) meses y así sucesivamente año con año durante el Plazo de Vigencia (según dicho término se define en la Cláusula Cuarta del Contrato).\n\nNo obstante lo anterior, las Partes acuerdan que, durante los dos primeros años del Plazo de Vigencia, el incremento relacionado en el párrafo inmediato anterior estará topado en todo momento al 8% (ocho por ciento) anual.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('c0c8e39d-0f1b-4a74-b3e4-ecbdf8752347', 'Common Area Maintenance Charges', '17', '14', 'MANTENIMIENTO Y OPERACIÓN DEL CENTRO COMERCIAL', E'- The Subtenant must pay a monthly maintenance fee to the Sublandlord starting from the Delivery Date.\n- This fee is 15% of the current Fixed Rent plus applicable VAT, initially set at $39,095.10 plus VAT.\n- The Maintenance Fee is separate from the Fixed Rent and will increase annually as per the contract.\n- The fee covers maintenance, cleaning, security, insurance, utilities, and upkeep of common areas and equipment in the shopping center.\n- Payment is due in advance each month, even if the Subtenant doesn''t use all common areas.\n- In extraordinary events, the Sublandlord can increase the fee, provided it''s shared among all tenants and the Subtenant is notified at least 5 days before the due date.\n- The Subtenant is responsible for maintaining and cleaning their own commercial space.', E'La Subarrendataria se obliga a pagar mensualmente a la Subarrendadora a partir de la Fecha de Entrega, por concepto de cuota por gastos de mantenimiento de las Áreas Comunes, equipos e instalaciones comunes del Centro Comercial, la cantidad que resulte de multiplicar por el 15% (quince por ciento) la Renta Fija vigente, más el IVA aplicable, la cual, a la fecha de la firma del Contrato, consiste en la cantidad de $39,095.10 (treinta y nueve mil noventa y cinco pesos 10/100, moneda nacional) más el IVA aplicable misma que tendrá el mismo tratamiento que la Renta Fija (la "Cuota de Mantenimiento"), sin considerarse incluida y/o parte de esta, en el entendido de que la Cuota de Mantenimiento será incrementada anualmente de conformidad con lo establecido en la Cláusula Segunda del Contrato, sobre incremento de la Renta Fija.\n\nLa Cuota de Mantenimiento incluye, de manera enunciativa más no limitativa, gastos de mantenimiento, limpieza, seguridad, vigilancia, seguros contra todo riesgo para cubrir daños materiales en el Centro Comercial, por fuego y/o rayo, inundaciones, temblor o terremoto, huelgas, alborotos populares o vandalismo, o cualquier otro acto asegurable, seguros de responsabilidad civil, energía eléctrica, agua, mantenimiento de equipos de aire acondicionado, elevadores, cualquier otro equipo electromecánico y cualquier otro equipo que exista o que llegare a instalarse en un futuro, incluyendo las vialidades, estacionamientos, accesos, azoteas, rampas y demás gastos de administración y mantenimiento del Centro Comercial. \n\nLa Cuota de Mantenimiento se pagará por mensualidades adelantadas, en forma íntegra aun cuando no haga uso total o parcial de todas las Áreas Comunes, juntamente con el importe de la Renta Fija, en términos de lo establecido en la Cláusula Segunda de este Contrato. \n\nIndependientemente de lo establecido en el párrafo precedente, en el caso de que se presentare un evento extraordinario, la Subarrendadora podrá incrementar el monto y/o el porcentaje de la Cuota de Mantenimiento, siempre y cuando (i) dicho incremento sea prorrateado entre la totalidad de los locales comerciales del Centro Comercial; y (ii) la Subarrendadora notifique dicho incremento por escrito a la Subarrendataria con por lo menos 5 (cinco) días de anticipación a la fecha de pago correspondiente. Por último, la Subarrendataria asume la obligación de realizar, por su cuenta y cargo, el pago del mantenimiento, conservación, y de cualquier otro gasto relacionado directamente con la operación del Local Comercial, así como la limpieza del Local Comercial, de tal forma que siempre se encuentre en óptimas condiciones.');
