ost_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"grid_id":57645,"grid_name":"Estadio Guadalajara","grid_full_address":"2955 Calzada Independencia Norte Y Eutimio Pizon, SUB-B, Rancho Nuevo, Guadalajara, Jalisco 44240","map_addr_1":"2955 Calzada Independencia Norte Y Eutimio Pizon","map_addr_2":"SUB-B","map_city_state_zip":"Rancho Nuevo, Guadalajara, Jalisco 44240","grid_brand":"Planet Fitness","location_created_at":"2025-09-25 16:47:22","active_lease_count_over_time":50867,"location_count_over_time":57645,"remaining_rent_liability_over_time":50867,"base_rent_current_month":"239818.2500","cam_current_month":"23981.8300","base_rent_next_month":"239818.2500","cam_next_month":"23981.8300","base_rent_per_square_meter":"2100.00","cam_per_square_meter":"210.00","base_rent_per_year":"2877819.0000","cam_per_year":"287781.9600"}'::jsonb);
