impuesto, derecho o aprovechamiento que dispongan las leyes fiscales mexicanas Federales, Estatales o Municipales, vigentes y que sea trasladable a terceros, haciendo en su caso las retenciones que por disposición de las mismas leyes deban hacerse.', 959273, false, '{"lease_total_rent_next_month":"263800.0800","total_monthly_rent":"263800.0800","annual_gross_rent":"3165600.9600","daily_gross_rent":"8672.87934247","recurring_rent_annual":"3165600.9600","lease_most_recent_note":"No","see_lease_for_details":"No","lease_is_silent":"No","rtr_enabled":1,"base_rent_current_month":"239818.2500","cam_current_month":"23981.8300","base_rent_next_month":"239818.2500","cam_next_month":"23981.8300","base_rent_per_square_meter":"2100.00","cam_per_square_meter":"210.00","base_rent_per_year":"2877819.0000","cam_per_year":"287781.9600"}'::jsonb);
