INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('95ae0e6e-1db8-45a1-b834-58094c31ada5', 'Common Area Maintenance Charges', '3', '4', 'CONTRAPRESTACIÓN', E'- El subarrendatario debe pagar una cuota de mantenimiento del 10% de la renta mensual.\n- Este pago comienza cuando el negocio inicia operaciones en el área comercial.\n- A la cuota de mantenimiento se le añadirá el impuesto al valor agregado (IVA) o cualquier impuesto que lo reemplace.\n- El subarrendatario no tiene que pagar por gastos de publicidad del centro comercial.', 'Adicionalmente EL SUBARRENDATARIO deberá cubrir una cuota de mantenimiento equivalente al 10% de la renta mensual actual vigente, dicha cantidad se comenzará a pagar a partir de la apertura o inicio de operaciones del negocio que operará en EL ÁREA COMERCIAL, En el entendido que a dicha cantidad se le agregará el correspondiente impuesto al valor agregado o el impuesto que en su momento llegare a sustituirlo. Las Partes convienen que EL SUBARRENDATARIO no participará en los gastos de Publicidad del Centro Comercial por lo que no se generará cantidad alguno por concepto de publicidad a cargo de éste.');
INSERT INTO lease_critical_clauses (lease_id, clause_type, page_number, section_number, lease_document_header, ai_summary, original_language) VALUES ('95ae0e6e-1db8-45a1-b834-58094c31ada5', 'Late Fees', '3', '2', 'CONTRAPRESTACIÓN', E'- You must email the proof of transfer to cuentasporcobrar@soriana.com, addressed to the Sub Dirección de Cobranza, within the first ten days of the month.\n- If payment is not made by the eleventh day, late interest will be added to the outstanding balance.\n- The interest rate is three times the TIIE rate published by Banxico, prorated for the duration of the delay.\n- If there are outstanding rents or interest, any payment made will first cover the interest, and the remainder will go towards the rent owed.\n- If rent is not paid within the first ten days of the month, a 4% monthly late interest will be added from the eleventh day, prorated for the duration of the delay.\n- Payments will first cover interest, then any remaining amount will go towards the rent owed.', E'Deberá de informar mediante correo electrónico a cuentasporcobrar@soriana.com a la atención de la Sub Dirección de Cobranza adjuntando el comprobante de transferencia, dentro de los primeros diez días naturales del mes que corresponda, sobre el entendido que a partir del onceavo día se acumularán al saldo insoluto, intereses moratorios, calculados a razón de la tasa anualizada que resulte de multiplicar por 3 (tres) la TASA DE INTERES INTERBANCARIA DE EQUILIBRIO, publicada mensualmente por Banxico, prorrateado durante el tiempo que permanezca en mora; en caso de existir adeudos por rentas o intereses, EL SUBARRENDATARIO reconoce y acepta que cualquier cantidad que abonase se aplicará primero a cubrir los intereses, y en su caso, el restante a cuenta de las rentas adeudadas.\n\nEn caso de que EL SUBARRENDATARIO no realice el pago de la Renta dentro de los primeros diez días naturales del mes que corresponda, sobre el entendido que a partir del décimo primer día se acumularán al saldo insoluto, intereses moratorios, a razón del 4% (cuatro por ciento) mensual, prorrateado durante el tiempo que permanezca en mora; en caso de existir adeudos por rentas o intereses, EL SUBARRENDATARIO reconoce y acepta que cualquier cantidad que abonase se aplicará primero a cubrir los intereses, y en su caso, el restante a cuenta de las rentas adeudadas.');
